83	pub type Fields = HashMap<String, String>;
84	
85	#[derive(Debug, Clone)]
86	pub struct LogEntry {
87	    pub level: LogLevel,
88	    pub message: String,
89	    pub fields: Fields,
90	}
91	
92	impl LogEntry {
93	    pub fn new(level: LogLevel, message: impl Into<String>) -> Self {
94	        Self {
95	            level,
96	            message: message.into(),
97	            fields: HashMap::new(),
98	        }
99	    }
100	
101	    pub fn with_field(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
102	        self.fields.insert(key.into(), value.into());
103	        self
104	    }
105	
106	    pub fn with_fields(mut self, fields: Fields) -> Self {
107	        self.fields.extend(fields);
108	        self
109	    }
110	
111	    /// Format: `[LEVEL] message | key1=value1 key2=value2`
112	    pub fn format(&self) -> String {
113	        let mut out = format!("[{}] {}", self.level, self.message);
114	        if !self.fields.is_empty() {
115	            out.push_str(" | ");
116	            let mut pairs: Vec<_> = self.fields.iter().collect();
117	            pairs.sort_by_key(|(k, _)| (*k).clone());
118	            let parts: Vec<String> = pairs.iter().map(|(k, v)| format!("{k}={v}")).collect();
119	            out.push_str(&parts.join(" "));
120	        }
121	        out
122	    }
123	}
