128	
129	pub struct Logger {
130	    level: Mutex<LogLevel>,
131	    sink: Mutex<Box<dyn Write + Send>>,
132	    entries: Mutex<Vec<LogEntry>>,
133	}
134	
135	impl Logger {
136	    pub fn new(level: LogLevel) -> Self {
137	        Self {
138	            level: Mutex::new(level),
139	            sink: Mutex::new(Box::new(io::sink())),
140	            entries: Mutex::new(Vec::new()),
141	        }
142	    }
143	
144	    pub fn with_writer(level: LogLevel, writer: impl Write + Send + 'static) -> Self {
145	        Self {
146	            level: Mutex::new(level),
147	            sink: Mutex::new(Box::new(writer)),
148	            entries: Mutex::new(Vec::new()),
149	        }
150	    }
151	
152	    pub fn set_level(&self, level: LogLevel) {
153	        *self.level.lock().unwrap() = level;
154	    }
155	
156	    pub fn level(&self) -> LogLevel {
157	        *self.level.lock().unwrap()
158	    }
159	
160	    /// Returns a clone of all recorded entries (useful for testing).
161	    pub fn entries(&self) -> Vec<LogEntry> {
162	        self.entries.lock().unwrap().clone()
163	    }
164	
165	    pub fn log(&self, entry: LogEntry) -> Result<(), LoggerError> {
166	        if entry.level < self.level() {
167	            return Ok(());
168	        }
169	
170	        let formatted = entry.format();
171	
172	        self.entries.lock().unwrap().push(entry);
173	
174	        let mut sink = self.sink.lock().unwrap();
175	        writeln!(sink, "{formatted}")?;
176	        Ok(())
177	    }
178	
179	    pub fn trace(&self, msg: impl Into<String>) -> Result<(), LoggerError> {
180	        self.log(LogEntry::new(LogLevel::Trace, msg))
181	    }
182	
183	    pub fn debug(&self, msg: impl Into<String>) -> Result<(), LoggerError> {
184	        self.log(LogEntry::new(LogLevel::Debug, msg))
185	    }
186	
187	    pub fn info(&self, msg: impl Into<String>) -> Result<(), LoggerError> {
188	        self.log(LogEntry::new(LogLevel::Info, msg))
189	    }
190	
191	    pub fn warn(&self, msg: impl Into<String>) -> Result<(), LoggerError> {
192	        self.log(LogEntry::new(LogLevel::Warn, msg))
193	    }
194	
195	    pub fn error(&self, msg: impl Into<String>) -> Result<(), LoggerError> {
196	        self.log(LogEntry::new(LogLevel::Error, msg))
197	    }
198	
199	    pub fn clear(&self) {
200	        self.entries.lock().unwrap().clear();
201	    }
202	}
