209	mod tests {
210	    use super::*;
211	
212	    fn test_logger() -> Logger {
213	        Logger::new(LogLevel::Trace)
214	    }
215	
216	    // ---- LogLevel -----------------------------------------------------------
217	
218	    #[test]
219	    fn test_log_level_ordering() {
220	        assert!(LogLevel::Trace < LogLevel::Debug);
221	        assert!(LogLevel::Debug < LogLevel::Info);
222	        assert!(LogLevel::Info < LogLevel::Warn);
223	        assert!(LogLevel::Warn < LogLevel::Error);
224	    }
225	
226	    #[test]
227	    fn test_log_level_display() {
228	        assert_eq!(LogLevel::Trace.to_string(), "TRACE");
229	        assert_eq!(LogLevel::Debug.to_string(), "DEBUG");
230	        assert_eq!(LogLevel::Info.to_string(), "INFO");
231	        assert_eq!(LogLevel::Warn.to_string(), "WARN");
232	        assert_eq!(LogLevel::Error.to_string(), "ERROR");
233	    }
234	
235	    #[test]
236	    fn test_log_level_from_str_valid() {
237	        assert_eq!("trace".parse::<LogLevel>().unwrap(), LogLevel::Trace);
238	        assert_eq!("DEBUG".parse::<LogLevel>().unwrap(), LogLevel::Debug);
239	        assert_eq!("Info".parse::<LogLevel>().unwrap(), LogLevel::Info);
240	        assert_eq!("warn".parse::<LogLevel>().unwrap(), LogLevel::Warn);
241	        assert_eq!("ERROR".parse::<LogLevel>().unwrap(), LogLevel::Error);
242	    }
243	
244	    #[test]
245	    fn test_log_level_from_str_invalid() {
246	        assert!("".parse::<LogLevel>().is_err());
247	        assert!("verbose".parse::<LogLevel>().is_err());
248	        assert!("123".parse::<LogLevel>().is_err());
249	    }
