251	    // ---- LogEntry -----------------------------------------------------------
252	
253	    #[test]
254	    fn test_entry_format_no_fields() {
255	        let entry = LogEntry::new(LogLevel::Info, "hello");
256	        assert_eq!(entry.format(), "[INFO] hello");
257	    }
258	
259	    #[test]
260	    fn test_entry_format_with_fields() {
261	        let entry = LogEntry::new(LogLevel::Error, "oops")
262	            .with_field("code", "500")
263	            .with_field("path", "/api");
264	        assert_eq!(entry.format(), "[ERROR] oops | code=500 path=/api");
265	    }
266	
267	    #[test]
268	    fn test_entry_fields_sorted() {
269	        let entry = LogEntry::new(LogLevel::Info, "msg")
270	            .with_field("z", "1")
271	            .with_field("a", "2")
272	            .with_field("m", "3");
273	        assert_eq!(entry.format(), "[INFO] msg | a=2 m=3 z=1");
274	    }
275	
276	    #[test]
277	    fn test_entry_with_fields_map() {
278	        let mut fields = Fields::new();
279	        fields.insert("x".into(), "1".into());
280	        fields.insert("y".into(), "2".into());
281	        let entry = LogEntry::new(LogLevel::Debug, "data").with_fields(fields);
282	        assert!(entry.fields.len() == 2);
283	    }
284	
285	    // ---- Logger basic operations --------------------------------------------
286	
