74	fn int_to_roman(mut n: u32) -> Result<String, String> {
75	    if n == 0 {
76	        return Err("zero has no Roman numeral representation".to_string());
77	    }
78	    if n > 3999 {
79	        return Err(format!("value {n} exceeds maximum representable (3999)"));
80	    }
81	
82	    let mut result = String::new();
83	    for &(value, symbol) in ROMAN_VALUES {
