92	fn roman_to_int(s: &str) -> Result<u32, String> {
93	    if s.is_empty() {
94	        return Err("empty Roman numeral".to_string());
95	    }
96	
97	    let upper = s.to_ascii_uppercase();
98	    let bytes = upper.as_bytes();
99	
100	    // Map a single Roman character to its numeric value.
101	    fn char_value(c: u8) -> Option<u32> {
102	        match c {
103	            b'I' => Some(1),
104	            b'V' => Some(5),
105	            b'X' => Some(10),
106	            b'L' => Some(50),
107	            b'C' => Some(100),
108	            b'D' => Some(500),
109	            b'M' => Some(1000),
110	            _ => None,
111	        }
112	    }
113	
114	    // Validate characters.
115	    for &b in bytes {
116	        if char_value(b).is_none() {
117	            return Err(format!("invalid Roman character: '{}'", b as char));
118	        }
119	    }
120	
121	    // Walk left-to-right: if a smaller value precedes a larger one, subtract it.
122	    let mut total: u32 = 0;
123	    let len = bytes.len();
124	
125	    for i in 0..len {
126	        let val = char_value(bytes[i]).unwrap();
127	        let next_val = if i + 1 < len {
128	            char_value(bytes[i + 1]).unwrap()
129	        } else {
130	            0
131	        };
132	
133	        if val < next_val {
134	            // Subtractive pair — must be one of: IV, IX, XL, XC, CD, CM.
135	            if !matches!(
136	                (val, next_val),
137	                (1, 5)
138	                    | (1, 10)
139	                    | (10, 50)
140	                    | (10, 100)
141	                    | (100, 500)
142	                    | (100, 1000)
143	            ) {
144	                return Err(format!(
145	                    "invalid subtractive pair: {}{}",
146	                    bytes[i] as char,
