156	    // Verify the result round-trips to the canonical form.
157	    let canonical = int_to_roman(total)?;
158	    if canonical != upper {
159	        return Err(format!(
160	            "non-canonical Roman numeral: expected {canonical}, got {upper}"
161	        ));
162	    }
163	
164	    Ok(total)
165	}
